use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let left: Vec<Value> = match input.get("left") {
        Some(v) => v.as_array().cloned().unwrap_or_default(),
        None => return json!([[]]),
    };

    let right: Vec<Value> = match input.get("right") {
        Some(v) => v.as_array().cloned().unwrap_or_default(),
        None => return json!([[]]),
    };

    let mut left_map: std::collections::HashMap<String, i64> = std::collections::HashMap::new();
    let mut right_map: std::collections::HashMap<String, i64> = std::collections::HashMap::new();

    for row in &left {
        if let [key, value] = row.as_array().unwrap_or(&vec![]) {
            if let Some(k) = key.as_str() {
                if let Some(v) = value.as_i64() {
                    left_map.insert(k.to_string(), v);
                }
            }
        }
    }

    for row in &right {
        if let [key, value] = row.as_array().unwrap_or(&vec![]) {
            if let Some(k) = key.as_str() {
                if let Some(v) = value.as_i64() {
                    right_map.insert(k.to_string(), v);
                }
            }
        }
    }

    let mut result = Vec::new();
    let mut keys: Vec<String> = left_map.keys().cloned().collect();
    keys.sort();

    for key in keys {
        if let Some(&left_val) = left_map.get(&key) {
            if let Some(&right_val) = right_map.get(&key) {
                result.push(json!([key, left_val, right_val]));
            }
        }
    }

    json!(result)
}

fn json<T>(value: T) -> Value
where
    T: serde::Serialize,
{
    serde_json::to_value(value).unwrap()
}
